export const FACILITIES={airport:{name:'Airport zone',width:3,height:5,cost:50,upkeep:30},seaport:{name:'Seaport zone',width:2,height:6,cost:50,upkeep:20}};
export function recomputeFacilities(c){const tiles=c.tiles,n=Math.sqrt(tiles.length),assigned=new Set(),plots=[],ocean=new Set(),q=[];
 for(let i=0;i<tiles.length;i++){const t=tiles[i];if(t.level||t.rubble||!FACILITIES[t.type])t.facilityAbandoned=false;t.facilityRoot=null;t.facilityReady=false;t.facilityReason='';if(t.terrain==='water'&&(t.x===0||t.y===0||t.x===n-1||t.y===n-1)){ocean.add(i);q.push(i);}}
 for(let k=0;k<q.length;k++){const t=tiles[q[k]];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=t.x+dx,y=t.y+dy,j=y*n+x;if(x>=0&&y>=0&&x<n&&y<n&&tiles[j].terrain==='water'&&!ocean.has(j)){ocean.add(j);q.push(j);}}}
 for(let i=0;i<tiles.length;i++){const t=tiles[i],f=FACILITIES[t.type];if(!f||assigned.has(i))continue;let found=null;for(const [w,h]of [[f.width,f.height],[f.height,f.width]]){if(t.x+w>n||t.y+h>n)continue;const ids=[];for(let y=t.y;y<t.y+h;y++)for(let x=t.x;x<t.x+w;x++)ids.push(y*n+x);if(ids.every(j=>tiles[j].elevation===t.elevation&&tiles[j].type===t.type&&!assigned.has(j))){found={root:i,type:t.type,x:t.x,y:t.y,width:w,height:h,ids};break;}}if(!found)continue;
 const members=found.ids.map(j=>tiles[j]),powered=members.every(u=>u.powered),watered=members.every(u=>u.watered),road=c.finance.roadCondition>20&&members.some(u=>u.roadIds.length),shore=members.some(u=>[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>{const x=u.x+dx,y=u.y+dy;return x>=0&&y>=0&&x<n&&y<n&&ocean.has(y*n+x);}));found.ready=members.every(u=>!u.radiation&&!u.rubble&&!u.fire)&&powered&&watered&&road&&(t.type!=='seaport'||shore);found.developed=members.every(u=>u.level>0);found.abandoned=members.every(u=>u.facilityAbandoned)&&!found.developed;found.operating=found.ready&&found.developed;found.reason=members.some(u=>u.radiation)?'Radiation contamination prevents development. Relocate this facility.':members.some(u=>u.rubble)?'Clear rubble and restore services to the damaged site.':!powered?'Connect electricity to every tile.':!watered?'Supply water to the whole zone.':!road?'Connect a nearby road.':t.type==='seaport'&&!shore?'Needs a shoreline with a continuous water path to the map edge.':!found.developed?'Ready to develop. Run the city for six months.':'Operating: businesses can reach outside markets.';
 if(found.abandoned)found.reason=found.ready?'Abandoned facility. Services restored: keep them supplied for '+Math.max(0,6-Math.min(...members.map(u=>u.age)))+' more months to reopen.':'Abandoned facility. '+found.reason;
 for(const j of found.ids){assigned.add(j);tiles[j].facilityRoot=i;tiles[j].facilityReady=found.ready;tiles[j].facilityReason=found.reason;}plots.push(found);}
 for(const t of tiles)if(FACILITIES[t.type]&&t.facilityRoot===null)t.facilityReason=`Needs a clear ${FACILITIES[t.type].width} × ${FACILITIES[t.type].height} rectangle of matching zoning.`;
 const activeAirports=plots.filter(p=>p.type==='airport'&&p.operating).length,activeSeaports=plots.filter(p=>p.type==='seaport'&&p.operating).length;
 return{abandonedFacilities:plots.filter(p=>p.abandoned).length,facilityPlots:plots,activeAirports,activeSeaports,facilityUpkeep:plots.filter(p=>p.developed).reduce((v,p)=>v+FACILITIES[p.type].upkeep,0)};
}
export function advanceFacilities(c){for(const p of c.stats.facilityPlots){const tiles=p.ids.map(i=>c.tiles[i]);if(p.ready){for(const t of tiles){t.age++;t.stress=0;}if(tiles.every(t=>t.age>=6))for(const t of tiles){t.level=1;t.facilityAbandoned=false;}}else{for(const t of tiles){t.age=0;t.stress++;}if(tiles.every(t=>t.stress>=6))for(const t of tiles){if(t.level)t.facilityAbandoned=true;t.level=0;}}}}
